package com.citacloud.springboot.contacloud.app.views;

import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.models.*;import com.citacloud.springboot.contacloud.app.security.TenantContext;import com.citacloud.springboot.contacloud.app.services.*;import com.citacloud.springboot.contacloud.app.views.components.*;
import com.vaadin.flow.component.*;import com.vaadin.flow.component.combobox.ComboBox;import com.vaadin.flow.component.confirmdialog.ConfirmDialog;import com.vaadin.flow.component.datepicker.DatePicker;import com.vaadin.flow.component.dialog.Dialog;import com.vaadin.flow.component.grid.Grid;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.notification.Notification;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.component.select.Select;import com.vaadin.flow.component.textfield.*;import com.vaadin.flow.data.value.ValueChangeMode;import com.vaadin.flow.router.*;import com.vaadin.flow.server.StreamResource;import com.vaadin.flow.server.VaadinSession;import jakarta.annotation.security.PermitAll;
import java.io.ByteArrayInputStream;import java.math.BigDecimal;import java.text.DecimalFormat;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;

@Route(value="inventario/transferencias",layout=MainLayout.class) @PageTitle("Transferencias de inventario | ContaCloud") @PermitAll
public class InventarioTransferenciasView extends VerticalLayout implements BeforeEnterObserver{
 private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd/MM/yyyy"),TIME=DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm");private static final DecimalFormat NUMBER=new DecimalFormat("#,##0.####");
 private final TransferenciaInventarioService service;private final TransferenciaInventarioDocumentoService documents;private final EmpresaModuloService modules;private TransferenciaInventarioCatalogosDto catalogs;
 private final TextField search=new TextField("Buscar");private final DatePicker from=date("Desde"),to=date("Hasta");private final Select<EstadoTransferenciaInventario> state=new Select<>();
 private final ComboBox<TransferenciaInventarioCatalogosDto.Sucursal> sourceBranch=new ComboBox<>("Sucursal origen"),destinationBranch=new ComboBox<>("Sucursal destino");private final ComboBox<TransferenciaInventarioCatalogosDto.Almacen> sourceWarehouse=new ComboBox<>("Almacén origen"),destinationWarehouse=new ComboBox<>("Almacén destino");
 private final AppGrid<TransferenciaInventarioDto> grid=new AppGrid<>(TransferenciaInventarioDto.class);private final AppPagination pagination;
 public InventarioTransferenciasView(TransferenciaInventarioService service,EmpresaModuloService modules){this(service,null,modules);}
 @org.springframework.beans.factory.annotation.Autowired
 public InventarioTransferenciasView(TransferenciaInventarioService service,TransferenciaInventarioDocumentoService documents,EmpresaModuloService modules){this.service=service;this.documents=documents;this.modules=modules;addClassName("cc-page");setPadding(false);setSpacing(false);setWidthFull();Component add=can("inventario_transferencias.crear")?new AppActionButton(ActionType.NEW,ButtonSize.MAIN,"Nueva transferencia",e->openForm(null)):null;add(add==null?new AppPageHeader("TRANSFERENCIAS DE INVENTARIO","Transfiere productos entre almacenes con trazabilidad completa."):new AppPageHeader("TRANSFERENCIAS DE INVENTARIO","Transfiere productos entre almacenes con trazabilidad completa.",add));filters();configureGrid();pagination=new AppPagination(r->load());HorizontalLayout row=new HorizontalLayout(search,from,to,state,sourceBranch,sourceWarehouse,destinationBranch,destinationWarehouse);row.addClassName("cc-filter-bar");row.setAlignItems(Alignment.END);row.setWidthFull();add(row,grid,pagination);}
 @Override public void beforeEnter(BeforeEnterEvent e){if(!modules.habilitado("INVENTARIO")||!can("inventario_transferencias.ver")){Notification.show("No tienes permiso para acceder a esta opción.");e.rerouteTo(DashboardView.class);return;}try{catalogs=service.catalogos(null);setCatalogs();load();}catch(RuntimeException ex){error(ex,"No fue posible cargar las transferencias de inventario.");}}
 private void filters(){
  search.setPlaceholder("Número, referencia, origen o destino...");search.setClearButtonVisible(true);search.setValueChangeMode(ValueChangeMode.LAZY);
  state.setLabel("Estado");state.setItems(EstadoTransferenciaInventario.values());state.setItemLabelGenerator(x->x==null?"Todos":x.getEtiqueta());state.setEmptySelectionCaption("Todos");state.setEmptySelectionAllowed(true);
  for(var x:List.of(sourceBranch,destinationBranch)){x.setClearButtonVisible(true);x.setItemLabelGenerator(TransferenciaInventarioCatalogosDto.Sucursal::nombre);}
  for(var x:List.of(sourceWarehouse,destinationWarehouse)){x.setClearButtonVisible(true);x.setItemLabelGenerator(a->a.nombre()+" · "+a.sucursal());}
  for(HasValue<?,?> f:List.of(search,from,to,state,sourceWarehouse,destinationWarehouse))f.addValueChangeListener(e->{if(e.isFromClient())reset();});
  sourceBranch.addValueChangeListener(e->{if(e.isFromClient()){sourceWarehouse.clear();sourceWarehouse.setItems(warehouses(e.getValue()));reset();}});
  destinationBranch.addValueChangeListener(e->{if(e.isFromClient()){destinationWarehouse.clear();destinationWarehouse.setItems(warehouses(e.getValue()));reset();}});
 }
 private void setCatalogs(){sourceBranch.setItems(catalogs.sucursales());destinationBranch.setItems(catalogs.sucursales());sourceWarehouse.setItems(catalogs.almacenes());destinationWarehouse.setItems(catalogs.almacenes());}
 private void configureGrid(){grid.addColumn(x->DATE.format(x.fecha())).setHeader("Fecha").setAutoWidth(true);grid.addColumn(TransferenciaInventarioDto::numero).setHeader("Número").setAutoWidth(true);grid.addColumn(x->x.sucursalOrigen()+" · "+x.almacenOrigen()).setHeader("Origen").setFlexGrow(1);grid.addColumn(x->x.sucursalDestino()+" · "+x.almacenDestino()).setHeader("Destino").setFlexGrow(1);grid.addColumn(x->x.tipo().getEtiqueta()).setHeader("Tipo").setAutoWidth(true);grid.addComponentColumn(x->badge(x.estado())).setHeader("Estado").setAutoWidth(true);grid.addComponentColumn(this::actions).setHeader("Acciones").setAutoWidth(true).setFlexGrow(0);grid.setEmptyStateText("No hay transferencias de inventario registradas.");}
 private Component actions(TransferenciaInventarioDto x){HorizontalLayout h=new HorizontalLayout();h.addClassName("cc-grid-actions");h.setPadding(false);h.setSpacing(false);h.add(new AppActionButton(ActionType.VIEW,ButtonSize.GRID_ACTION,"Ver transferencia",e->openDetail(x.id())));if(x.estado()==EstadoTransferenciaInventario.DRAFT&&can("inventario_transferencias.editar"))h.add(new AppActionButton(ActionType.EDIT,ButtonSize.GRID_ACTION,"Editar transferencia",e->openForm(x.id())));return h;}
 private void load(){if(catalogs==null)return;try{var r=pagination.currentRequest();var page=service.buscar(search.getValue(),from.getValue(),to.getValue(),state.getValue(),id(sourceBranch),id(sourceWarehouse),id(destinationBranch),id(destinationWarehouse),r.page(),r.size());grid.setItems(page.getContent());pagination.setTotal(page.getTotalElements());}catch(RuntimeException ex){error(ex,"No fue posible cargar las transferencias de inventario.");}}
 private void reset(){pagination.reset();load();}

 private void openForm(UUID id){
  try{
   TransferenciaInventarioDto current=id==null?null:service.obtener(id);
   TransferenciaInventarioCatalogosDto initial=service.catalogos(current==null?null:current.almacenOrigenId());
   Dialog d=dialog(current==null?"NUEVA TRANSFERENCIA":"EDITAR TRANSFERENCIA",1200);
   DatePicker transferDate=date("Fecha");transferDate.setRequiredIndicatorVisible(true);transferDate.setValue(current==null?LocalDate.now():current.fecha());
   Select<TipoTransferenciaInventario> type=new Select<>();type.setLabel("Tipo");type.setItems(TipoTransferenciaInventario.values());type.setItemLabelGenerator(TipoTransferenciaInventario::getEtiqueta);type.setValue(current==null?TipoTransferenciaInventario.DIRECT:current.tipo());type.setRequiredIndicatorVisible(true);
   ComboBox<TransferenciaInventarioCatalogosDto.Almacen> sw=warehouseCombo("Almacén origen",initial.almacenes()),dw=warehouseCombo("Almacén destino",initial.almacenes());
   Span sourceBranchInfo=new Span("Selecciona un almacén"),destinationBranchInfo=new Span("Selecciona un almacén");sourceBranchInfo.addClassName("cc-secondary-text");destinationBranchInfo.addClassName("cc-secondary-text");
   VerticalLayout sourceBlock=warehouseBlock(sw,sourceBranchInfo),destinationBlock=warehouseBlock(dw,destinationBranchInfo);
   sw.addValueChangeListener(e->sourceBranchInfo.setText(e.getValue()==null?"Selecciona un almacén":e.getValue().sucursal()));dw.addValueChangeListener(e->destinationBranchInfo.setText(e.getValue()==null?"Selecciona un almacén":e.getValue().sucursal()));
   TextField reference=new TextField("Referencia");reference.setMaxLength(100);TextArea notes=new TextArea("Observación");notes.setMaxLength(1000);notes.addClassName("cc-dialog-span-2");
   if(current!=null){selectWarehouse(sw,current.almacenOrigenId());selectWarehouse(dw,current.almacenDestinoId());reference.setValue(value(current.referencia()));notes.setValue(value(current.notas()));}
   List<LineDraft> drafts=new ArrayList<>();if(current!=null)for(var line:current.lineas()){var product=initial.productos().stream().filter(p->p.id().equals(line.productoId())).findFirst().orElse(new TransferenciaInventarioCatalogosDto.Producto(line.productoId(),line.codigo(),line.producto(),line.unidadId(),line.unidad(),BigDecimal.ZERO,false));drafts.add(new LineDraft(product,line.cantidadDespachada()));}
   AppGrid<LineDraft> lineGrid=new AppGrid<>(LineDraft.class);lineGrid.addColumn(x->x.product.codigo()).setHeader("Código").setAutoWidth(true);lineGrid.addColumn(x->x.product.nombre()).setHeader("Producto").setFlexGrow(1);lineGrid.addColumn(x->x.product.unidad()).setHeader("Unidad").setAutoWidth(true);lineGrid.addColumn(x->number(x.product.existencia())).setHeader("Disponible").setAutoWidth(true);lineGrid.addColumn(x->number(x.quantity)).setHeader("Cantidad").setAutoWidth(true);lineGrid.addComponentColumn(x->{HorizontalLayout h=new HorizontalLayout();h.addClassName("cc-grid-actions");h.add(new AppActionButton(ActionType.EDIT,ButtonSize.GRID_ACTION,"Editar línea",e->lineForm(d,sw,drafts,x,lineGrid)),new AppActionButton(ActionType.DELETE,ButtonSize.GRID_ACTION,"Eliminar línea",e->{drafts.remove(x);lineGrid.setItems(drafts);}));return h;}).setHeader("Acciones").setAutoWidth(true);lineGrid.setItems(drafts);lineGrid.setEmptyStateText("Agrega al menos un producto.");
   AppActionButton addLine=new AppActionButton(ActionType.NEW,ButtonSize.MAIN,"Agregar producto",e->lineForm(d,sw,drafts,null,lineGrid));Div lineHead=new Div(new H3("PRODUCTOS"),addLine);lineHead.addClassName("cc-detail-heading");d.add(section("INFORMACIÓN GENERAL",transferDate,type,sourceBlock,destinationBlock,reference,notes),lineHead,lineGrid);
   UUID operationKey=UUID.randomUUID();
   java.util.function.Supplier<TransferenciaInventarioInput> input=()->new TransferenciaInventarioInput(transferDate.getValue(),type.getValue(),id(sw),id(dw),reference.getValue(),notes.getValue(),drafts.stream().map(x->new TransferenciaInventarioInput.Linea(x.product.id(),x.product.unidadId(),x.quantity)).toList(),current==null?null:current.version(),operationKey);
   AppActionButton save=new AppActionButton(ActionType.SAVE,ButtonSize.MAIN,"Guardar",e->{try{if(current==null)service.crear(input.get());else service.actualizar(current.id(),input.get());d.close();refresh();Notification.show("Transferencia guardada como borrador.");}catch(RuntimeException ex){error(ex,"No fue posible guardar la transferencia.");}});
   AppActionButton process=new AppActionButton(ActionType.ISSUE,ButtonSize.MAIN,type.getValue()==TipoTransferenciaInventario.DIRECT?"Guardar y confirmar":"Guardar y despachar",null);type.addValueChangeListener(e->process.setTooltipText(e.getValue()==TipoTransferenciaInventario.DIRECT?"Guardar y confirmar":"Guardar y despachar"));
   process.addClickListener(e->confirm(type.getValue()==TipoTransferenciaInventario.DIRECT?"Confirmar transferencia":"Despachar transferencia",type.getValue()==TipoTransferenciaInventario.DIRECT?"Se descontará el inventario del origen y se agregará al destino en una sola operación.":"Se descontará el inventario del origen y quedará registrado en tránsito.",()->{try{TransferenciaInventarioDto processed=service.guardarYProcesar(current==null?null:current.id(),input.get());d.close();refresh();Notification.show(type.getValue()==TipoTransferenciaInventario.DIRECT?"Transferencia confirmada.":"Transferencia despachada.");openPdfAfterProcess(processed);}catch(RuntimeException ex){error(ex,"No fue posible procesar la transferencia.");}}));
   d.getFooter().add(save,process,new AppActionButton(ActionType.CANCEL,ButtonSize.MAIN,"Cancelar",e->d.close()));d.open();
  }catch(RuntimeException ex){error(ex,"No fue posible abrir la transferencia.");}
 }


 private void lineForm(Dialog parent,ComboBox<TransferenciaInventarioCatalogosDto.Almacen> source,List<LineDraft> drafts,LineDraft current,Grid<LineDraft> table){if(source.getValue()==null){Notification.show("Selecciona primero el almacén origen.");return;}try{var available=service.catalogos(source.getValue().id()).productos();Dialog d=dialog(current==null?"AGREGAR PRODUCTO":"EDITAR PRODUCTO",700);ComboBox<TransferenciaInventarioCatalogosDto.Producto> product=new ComboBox<>("Producto");product.setItems(available);product.setItemLabelGenerator(x->x.codigo()+" · "+x.nombre()+" · Disponible: "+number(x.existencia()));product.setRequiredIndicatorVisible(true);BigDecimalField quantity=new BigDecimalField("Cantidad");quantity.setRequiredIndicatorVisible(true);if(current!=null){product.setValue(available.stream().filter(x->x.id().equals(current.product.id())).findFirst().orElse(current.product));quantity.setValue(current.quantity);}d.add(section("PRODUCTO",product,quantity));d.getFooter().add(new AppActionButton(ActionType.SAVE,ButtonSize.MAIN,"Guardar línea",e->{try{var p=product.getValue();if(p==null)throw new ReglaNegocioException("Selecciona un producto.");if(quantity.getValue()==null||quantity.getValue().signum()<=0)throw new ReglaNegocioException("La cantidad debe ser mayor que cero.");if(drafts.stream().anyMatch(x->x!=current&&x.product.id().equals(p.id())))throw new ReglaNegocioException("El producto ya fue agregado a la transferencia.");LineDraft n=new LineDraft(p,quantity.getValue());if(current==null)drafts.add(n);else drafts.set(drafts.indexOf(current),n);table.setItems(drafts);d.close();}catch(RuntimeException ex){error(ex,"No fue posible guardar la línea.");}}),new AppActionButton(ActionType.CANCEL,ButtonSize.MAIN,"Cancelar",e->d.close()));d.open();}catch(RuntimeException ex){error(ex,"No fue posible cargar los productos.");}}

 private void cancel(UUID id,Dialog parent){Dialog d=dialog("CANCELAR TRANSFERENCIA",650);TextArea reason=new TextArea("Motivo de cancelación");reason.setRequiredIndicatorVisible(true);reason.setWidthFull();d.add(reason);d.getFooter().add(new AppActionButton(ActionType.VOID,ButtonSize.MAIN,"Cancelar transferencia",e->{try{service.cancelar(id,reason.getValue());d.close();parent.close();refresh();Notification.show("Transferencia cancelada.");}catch(RuntimeException ex){error(ex,"No fue posible cancelar la transferencia.");}}),new AppActionButton(ActionType.CANCEL,ButtonSize.MAIN,"Cerrar",e->d.close()));d.open();}
 private void openDetail(UUID id){
  try{
   var x=service.obtener(id);Dialog d=dialog("TRANSFERENCIA DE INVENTARIO",1200);Div heading=new Div(new H2(x.numero()),badge(x.estado()));heading.addClassName("cc-detail-heading");
   d.add(heading,new AppDetailSection("INFORMACIÓN GENERAL").field("Fecha",DATE.format(x.fecha())).field("Tipo",x.tipo().getEtiqueta()).field("Almacén origen",x.almacenOrigen()).field("Sucursal origen",x.sucursalOrigen()).field("Almacén destino",x.almacenDestino()).field("Sucursal destino",x.sucursalDestino()).field("Referencia",display(x.referencia())).field("Observación",display(x.notas())));
   AppGrid<TransferenciaInventarioDto.Linea> table=new AppGrid<>(TransferenciaInventarioDto.Linea.class);table.addColumn(TransferenciaInventarioDto.Linea::codigo).setHeader("Código").setAutoWidth(true);table.addColumn(TransferenciaInventarioDto.Linea::producto).setHeader("Producto").setFlexGrow(1);table.addColumn(TransferenciaInventarioDto.Linea::unidad).setHeader("Unidad").setAutoWidth(true);table.addColumn(l->number(l.cantidadDespachada())).setHeader("Despachada").setAutoWidth(true);table.addColumn(l->number(l.cantidadRecibida())).setHeader("Recibida").setAutoWidth(true);table.addColumn(l->number(l.diferencia())).setHeader("Diferencia").setAutoWidth(true);table.setItems(x.lineas());
   d.add(table,new AppDetailSection("TRAZABILIDAD").field("Despachada",time(x.despachadaEn())).field("Despachada por",display(x.despachadaPor())).field("Recibida",time(x.recibidaEn())).field("Recibida por",display(x.recibidaPor())).field("Cancelada",time(x.canceladaEn())).field("Motivo",display(x.motivoCancelacion())));
   if(x.estado()==EstadoTransferenciaInventario.DRAFT&&can("inventario_transferencias.despachar")){String label=x.tipo()==TipoTransferenciaInventario.DIRECT?"Confirmar transferencia":"Despachar";d.getFooter().add(new AppActionButton(ActionType.ISSUE,ButtonSize.MAIN,label,e->confirm(label,"Esta operación modificará las existencias y no podrá editarse después.",()->{try{TransferenciaInventarioDto processed=x.tipo()==TipoTransferenciaInventario.DIRECT?service.confirmarDirecta(x.id()):service.despachar(x.id());d.close();refresh();Notification.show(x.tipo()==TipoTransferenciaInventario.DIRECT?"Transferencia confirmada.":"Transferencia despachada.");openPdfAfterProcess(processed);}catch(RuntimeException ex){error(ex,"No fue posible procesar la transferencia.");}})));}
   if((x.estado()==EstadoTransferenciaInventario.IN_TRANSIT||x.estado()==EstadoTransferenciaInventario.RECEIVED)&&can("inventario_transferencias.pdf"))d.getFooter().add(new AppActionButton(ActionType.PRINT,ButtonSize.MAIN,"Generar PDF",e->{try{openPdf(x.id());}catch(RuntimeException ex){error(ex,"No fue posible generar el PDF de la transferencia.");}}));
   if(x.estado()==EstadoTransferenciaInventario.IN_TRANSIT&&can("inventario_transferencias.recibir"))d.getFooter().add(new AppActionButton(ActionType.ACCEPT,ButtonSize.MAIN,"Recibir transferencia",e->confirm("Recibir transferencia","La mercancía saldrá de tránsito e ingresará al almacén destino.",()->{try{service.recibir(x.id());d.close();refresh();Notification.show("Transferencia recibida.");}catch(RuntimeException ex){error(ex,"No fue posible recibir la transferencia.");}})));
   if(x.estado()==EstadoTransferenciaInventario.DRAFT&&can("inventario_transferencias.cancelar"))d.getFooter().add(new AppActionButton(ActionType.VOID,ButtonSize.MAIN,"Cancelar transferencia",e->cancel(x.id(),d)));
   d.getFooter().add(new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",e->d.close()));d.open();
  }catch(RuntimeException ex){error(ex,"No fue posible consultar la transferencia.");}
 }

 private void refresh(){catalogs=service.catalogos(null);setCatalogs();load();}
 private void openPdfAfterProcess(TransferenciaInventarioDto transfer){try{openPdf(transfer.id());}catch(RuntimeException ex){Notification.show(transfer.tipo()==TipoTransferenciaInventario.DIRECT?"La transferencia fue confirmada correctamente, pero no fue posible generar el PDF. Puede generarlo nuevamente desde el detalle de la transferencia.":"La transferencia fue despachada correctamente, pero no fue posible generar el PDF. Puede generarlo nuevamente desde el detalle de la transferencia.");}}
 private void openPdf(UUID id){ArchivoPdfDto file=documents.generar(id);StreamResource resource=new StreamResource(file.nombreArchivo(),()->new ByteArrayInputStream(file.contenido()));resource.setContentType("application/pdf");resource.setCacheTime(0);var registration=VaadinSession.getCurrent().getResourceRegistry().registerResource(resource);UI.getCurrent().getPage().open(registration.getResourceUri().toString(),"_blank");}
 private static VerticalLayout warehouseBlock(ComboBox<TransferenciaInventarioCatalogosDto.Almacen> warehouse,Span branch){VerticalLayout block=new VerticalLayout(warehouse,branch);block.setPadding(false);block.setSpacing(false);block.setWidthFull();warehouse.setWidthFull();return block;}
 private static void confirm(String title,String text,Runnable action){ConfirmDialog c=new ConfirmDialog();c.setHeader(title);c.setText(text);c.setCancelable(true);c.setCancelText("Cancelar");c.setConfirmText("Confirmar");c.addConfirmListener(e->action.run());c.open();}
 private List<TransferenciaInventarioCatalogosDto.Almacen> warehouses(TransferenciaInventarioCatalogosDto.Sucursal b){return catalogs==null?List.of():filter(catalogs.almacenes(),b);}private static List<TransferenciaInventarioCatalogosDto.Almacen> filter(List<TransferenciaInventarioCatalogosDto.Almacen> ws,TransferenciaInventarioCatalogosDto.Sucursal b){return ws.stream().filter(x->b==null||b.id().equals(x.sucursalId())).toList();}
 private static ComboBox<TransferenciaInventarioCatalogosDto.Almacen> warehouseCombo(String l,List<TransferenciaInventarioCatalogosDto.Almacen> xs){var c=new ComboBox<TransferenciaInventarioCatalogosDto.Almacen>(l);c.setItems(xs);c.setItemLabelGenerator(x->x.nombre()+" · "+x.sucursal());c.setRequiredIndicatorVisible(true);return c;}
 private static void selectWarehouse(ComboBox<TransferenciaInventarioCatalogosDto.Almacen> c,UUID id){c.getListDataView().getItems().filter(x->Objects.equals(x.id(),id)).findFirst().ifPresent(c::setValue);}private static UUID id(ComboBox<?> c){Object x=c.getValue();if(x instanceof TransferenciaInventarioCatalogosDto.Sucursal y)return y.id();if(x instanceof TransferenciaInventarioCatalogosDto.Almacen y)return y.id();return null;}
 private static Div section(String title,Component... fields){Div s=new Div();s.addClassName("cc-form-section");H3 h=new H3(title);h.addClassName("cc-section-heading");Div f=new Div(fields);f.addClassName("cc-dialog-form");s.add(h,f);return s;}private static Dialog dialog(String title,int width){Dialog d=new Dialog();d.setHeaderTitle(title);d.setWidth("min("+width+"px, 96vw)");return d;}private static DatePicker date(String l){DatePicker d=new DatePicker(l);d.setLocale(new Locale("es","DO"));d.setPlaceholder("DD/MM/YYYY");d.setClearButtonVisible(true);return d;}private static Span badge(EstadoTransferenciaInventario s){Span b=new Span(s.getEtiqueta());String theme=s==EstadoTransferenciaInventario.RECEIVED?"success":s==EstadoTransferenciaInventario.CANCELLED?"error":s==EstadoTransferenciaInventario.IN_TRANSIT?"warning":"contrast";b.getElement().getThemeList().add("badge "+theme);return b;}private static String number(BigDecimal x){return x==null?"—":NUMBER.format(x);}private static String display(String x){return x==null||x.isBlank()?"—":x;}private static String value(String x){return x==null?"":x;}private static String time(OffsetDateTime x){return x==null?"—":TIME.format(x.atZoneSameInstant(ZoneId.systemDefault()));}private static boolean can(String p){return TenantContext.principalActual().permisos().contains(p);}private static void error(RuntimeException ex,String fallback){String m=ex instanceof ReglaNegocioException||ex instanceof RecursoNoEncontradoException?ex.getMessage():fallback;Notification.show(m==null||m.isBlank()?fallback:m);}private record LineDraft(TransferenciaInventarioCatalogosDto.Producto product,BigDecimal quantity){}
}


